/**
 * Lists every editable customer-facing email template for the superadmin
 * editor (app/superadmin/email-templates). Each entry's `id` MUST match the
 * templateId string passed to renderTemplate() at the real send call site
 * (grep for it to find the site) -- that's what links an override to an
 * actual email.
 *
 * `sampleHtml` is what the editor shows as a starting point when a template
 * has never been customized (no saved override yet). For the onboarding,
 * trial, and waitlist-nurture sequences it's generated by calling the real
 * shared functions with sample data, so it can never drift from what's
 * actually sent. For the ~20 standalone templates (one-off HTML inline at
 * their call site, not a shared function), sampleHtml is a copy of that
 * default, kept here only for the editor's starting point -- if you change
 * the inline default at a call site, update its copy here too, or the
 * editor's "start from current default" view goes stale for anyone who
 * hasn't customized that template yet. This never affects what's actually
 * sent: the real send path always reads its own local default directly.
 */
import { ONBOARDING_EMAILS } from '@/lib/onboarding-emails'
import { TRIAL_EMAILS, USER_EMAILS } from '@/lib/trial-emails'
import { getWaitlistNurtureEmail } from '@/lib/waitlist-nurture'

export interface RegisteredTemplate {
  id: string
  label: string
  group: string
  /** Token names usable as {{token}} in this template's HTML. */
  params: string[]
  /** Sample values for every param, used to render the live preview. */
  sampleParams: Record<string, string>
  /** Starting content when nothing has been customized yet. */
  sampleHtml: string
}

