  orgName:      'Sunrise Care Home',
  expiryDate:   '30 September 2026',
  deletionDate: '14 October 2026',
  price:        '£75',
  when:         '16 September 2026 at 14:32',
  kloeTitle:    'Safe: Safeguarding Systems, Processes and Practices',
  kloUrl:       'https://portal.alwaysready.uk/dashboard/kloes/sample-id',
  dueDate:      '23 September 2026',
  daysLeft:     '5',
  staffName:    'James Mitchell',
  fieldLabel:   'DBS Check',
  message:      'Thanks for flagging this. Evidence uploads accept .pdf, .docx, .xlsx, .jpg, .jpeg, and .png files.',
  reference:    'AR-0042',
  subject:      'Unable to upload evidence documents',
  followUpText: `If your issue has not been fully resolved or you have a follow-up question, please open a new support ticket from the <strong>Support</strong> section inside the platform and we'll be happy to help.`,
