  adminEmail:   'sarah@sunrisecarehome.co.uk',
  adminPassword: 'TempPass-8f2a1c',
  trialExpiry:  '30 September 2026',
  charityNote:  '',
  setupLink:    'https://portal.alwaysready.uk/account/setup?token=example',
  upgradeUrl:   'https://portal.alwaysready.uk/upgrade',
