      id:           `waitlist_nurture_${i}`,
      label:        `Waitlist ${i}: ${email.subject}`,
      group:        'Waitlist nurture sequence',
      params:       ['firstName'],
      sampleParams: { firstName: S.firstName },
      sampleHtml:   email.bodyHtml,
